#[derive(Debug, Clone)]
pub struct HopscotchMap<K, V> {
    entries: Vec<(K, V)>,
    bucket_count: usize,
}

impl<K, V> Default for HopscotchMap<K, V> {
    fn default() -> Self {
        Self::new()
    }
}

impl<K, V> HopscotchMap<K, V> {
    pub fn new() -> Self {
        Self {
            entries: Vec::new(),
            bucket_count: 0,
        }
    }

    pub fn size(&self) -> usize {
        self.entries.len()
    }

    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    pub fn overflow_size(&self) -> usize {
        0
    }

    pub fn reserve(&mut self, entry_capacity: usize) {
        let required = required_bucket_count(entry_capacity);
        if required > self.bucket_count {
            self.bucket_count = required;
        }
    }
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq,
{
    pub fn insert(&mut self, entry: (K, V)) -> bool {
        let (key, value) = entry;

        if self.entries.iter().any(|(existing, _)| existing == &key) {
            return false;
        }

        let next_len = self
            .entries
            .len()
            .checked_add(1)
            .expect("map length overflowed usize");

        if next_len > max_entries_for_buckets(self.bucket_count) {
            self.bucket_count = required_bucket_count(next_len);
        }

        self.entries.push((key, value));
        true
    }
}

pub fn required_bucket_count(entry_capacity: usize) -> usize {
    if entry_capacity == 0 {
        return 0;
    }

    // The observed binary grows once the load would exceed 7/8.
    let minimum_buckets = div_ceil((entry_capacity as u128) * 8, 7);
    let minimum_buckets = usize::try_from(minimum_buckets).expect("bucket count overflowed usize");

    minimum_buckets
        .checked_next_power_of_two()
        .expect("bucket count overflowed usize")
}

pub fn max_entries_for_buckets(bucket_count: usize) -> usize {
    usize::try_from((bucket_count as u128) * 7 / 8).expect("entry capacity overflowed usize")
}

fn div_ceil(lhs: u128, rhs: u128) -> u128 {
    (lhs + rhs - 1) / rhs
}

#[cfg(test)]
mod tests {
    use super::{max_entries_for_buckets, required_bucket_count, HopscotchMap};

    #[test]
    fn matches_observed_bucket_counts() {
        let cases = [
            (0, 0),
            (1, 2),
            (2, 4),
            (3, 4),
            (4, 8),
            (5, 8),
            (7, 8),
            (8, 16),
            (14, 16),
            (15, 32),
            (18, 32),
            (28, 32),
            (29, 64),
            (57, 64),
            (58, 128),
        ];

        for (count, expected) in cases {
            assert_eq!(required_bucket_count(count), expected);
        }
    }

    #[test]
    fn exposes_the_same_effective_load_factor() {
        assert_eq!(max_entries_for_buckets(2), 1);
        assert_eq!(max_entries_for_buckets(4), 3);
        assert_eq!(max_entries_for_buckets(8), 7);
        assert_eq!(max_entries_for_buckets(32), 28);
    }

    #[test]
    fn keeps_zero_overflow_for_this_black_box_model() {
        let mut map = HopscotchMap::new();
        map.reserve(18);

        for i in 0..18 {
            assert!(map.insert((i, i * 14)));
        }

        assert_eq!(map.size(), 18);
        assert_eq!(map.bucket_count(), 32);
        assert_eq!(map.overflow_size(), 0);
    }

    #[test]
    fn duplicate_keys_do_not_change_size() {
        let mut map = HopscotchMap::new();
        assert!(map.insert((1, 14)));
        assert!(!map.insert((1, 28)));
        assert_eq!(map.size(), 1);
    }
}

